{"HelperA.dfy": "A.ObserveMove(m, a, b);
    var m1 := K.Move(m, a, b);
    assert m1.Keys == (m.Keys - {a}) + {b};
    assert b in m1;
    assert c !in m1;
    assert b != c;
    A.ObserveMove(m1, b, c);
    var m2 := K.Move(m1, b, c);
    assert m2.Keys == (m1.Keys - {b}) + {c};
    A.ObserveMove(m, a, c);
    var m3 := K.Move(m, a, c);
    assert m3.Keys == (m.Keys - {a}) + {c};
    assert m2.Keys == m3.Keys;
    forall q0 | q0 in m2 ensures q0 in m3 && m2[q0] == m3[q0] {
        if q0 == c {
            assert m2[q0] == m1[b];
            assert m1[b] == m[a];
            assert m3[q0] == m[a];
        } else {
            assert q0 != c;
            assert q0 in m1;
            assert q0 != b;
            assert m2[q0] == m1[q0];
            assert q0 in m;
            assert q0 != a;
            assert m1[q0] == m[q0];
            assert m3[q0] == m[q0];
        }
    }
    A.Equal(m2, m3);"}

